B.bfA=new A.a9(B.c4,B.b_w,"Si es congelado, descong\xe9lalo en la nevera la noche antes y s\xe9calo bien.","El bacalao se separa en lascas al tocarlo (8-10 minutos en la salsa).",B.azK,B.b0E,B.aA9,null,null,B.t)
B.awM=s(["Cazuela baja (mejor de barro)","Cazo para las patatas"],t.s)
